   "text": "<div class=\"soc-text\"><p>У исполнителя <b>Квадратор</b> две команды, которым присвоены номера:</p> <p><b>1. возведи в квадрат</b></p> <p><b>2. вычти 2</b></p> <p>Первая из них возводит число на экране во вторую степень, вторая &#x2013; &nbsp;вычитает из числа 2.</p> <p>Составьте алгоритм получения <b>из числа 1 числа 49</b>, содержащий не более 5 команд. В ответе запишите только номера команд. </p> <p><i>(Например, 21212 &#x2013; &nbsp;это</i></p> <p><i>алгоритм</i></p> <p><i>вычти 2</i></p> <p><i>возведи в квадрат</i></p> <p><i>вычти 2</i></p> <p><i>возведи в квадрат</i></p> <p><i>вычти 2</i></p> <p><i>который преобразует число 5 в 47.)</i></p> <p>Если таких алгоритмов более одного, то запишите любой из них.</p></div>",
